    if (existingIndex >= 0) presets.splice(existingIndex, 1);
    presets.unshift(preset);
    await spindle.userStorage.setJson(STACK_PRESETS_FILE, presets.slice(0, STACK_PRESET_LIMIT), {
        indent: 2,
        userId
    });
